<script>
document.querySelectorAll('[data-copy-live-link]').forEach(function(button){button.addEventListener('click',async function(){var original=button.textContent.trim();try{await navigator.clipboard.writeText(window.location.href);button.textContent='Copied!';}catch(_){var field=document.createElement('textarea');field.value=window.location.href;document.body.appendChild(field);field.select();document.execCommand('copy');field.remove();button.textContent='Copied!';}window.setTimeout(function(){button.textContent=original;},1600);});});
</script>
